"use client";

import { FormEvent, useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";

export default function AdminLoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const signIn = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setLoading(true);
    setError("");
    const { error: authError } = await supabase.auth.signInWithPassword({ email, password });
    setLoading(false);
    if (authError) {
      setError("Unable to sign in with those credentials.");
      return;
    }
    router.replace("/");
    router.refresh();
  };

  const field =
    "w-full h-10 rounded-lg bg-white px-3 text-sm text-[#303030] shadow-[0_0_0_1px_rgba(0,0,0,0.2)] outline-none focus:shadow-[0_0_0_2px_#005bd3] transition-shadow";

  return (
    <main className="min-h-screen grid place-items-center bg-[#f1f1f1] p-6 text-[#303030] antialiased">
      <div className="w-full max-w-sm">
        <div className="flex items-center justify-center gap-2.5 mb-6">
          <div className="w-9 h-9 rounded-lg bg-[#1a1a1a] flex items-center justify-center p-1.5">
            <img src="/logo.png" alt="Royal Bengal" className="w-full h-full object-contain" />
          </div>
          <span className="text-base font-semibold text-[#1a1a1a]">Royal Bengal</span>
        </div>

        <form
          onSubmit={signIn}
          className="space-y-4 rounded-xl bg-white p-6 shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_2px_8px_rgba(0,0,0,0.06)]"
        >
          <header>
            <h1 className="text-xl font-semibold text-[#1a1a1a]">Log in</h1>
            <p className="mt-1 text-[13px] text-[#616161]">Continue to your store admin.</p>
          </header>

          {error && (
            <p role="alert" className="rounded-lg bg-[#fed1d7] px-3 py-2 text-[13px] text-[#8e0b21]">
              {error}
            </p>
          )}

          <label className="block space-y-1.5 text-[13px] font-medium">
            <span>Email</span>
            <input required type="email" autoComplete="username" value={email} onChange={(e) => setEmail(e.target.value)} className={field} />
          </label>
          <label className="block space-y-1.5 text-[13px] font-medium">
            <span>Password</span>
            <input required type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} className={field} />
          </label>

          <button
            disabled={loading}
            className="w-full h-10 rounded-lg bg-[#303030] hover:bg-[#1a1a1a] text-sm font-medium text-white disabled:opacity-60 transition-colors"
          >
            {loading ? "Signing in…" : "Log in"}
          </button>
          <p className="text-xs text-[#616161] text-center">Only accounts with an authorized staff role can sign in.</p>
        </form>
      </div>
    </main>
  );
}
